CREATE UNIQUE INDEX "attendance_teacher_date_unique" ON "attendance_records" USING btree ("teacher_id","attendance_date") WHERE "attendance_records"."type" = 'GURU' AND "attendance_records"."teacher_id" IS NOT NULL;